 // Surviving apostles/Christ are silhouette approximations, not invented old nave restoration.
 for(const u of[cu-3.9,cu+3.9]){boxUV(c,ledge,u,cv-3.9,.40,.37,9.6,10.0);boxUV(c,statue,u,cv-3.9,.26,.22,10.,11.3);const b=statue;boxUV(c,b,u,cv-3.9,.16,.16,11.3,11.7);}
