export function ownerF203Reconstruction(components:BuildingComponent[]){const stats:OwnerReconstructionStats={objects:0,vertices:0,triangles:0,originalVertices:0,sourceRetained:true,actualVisualAccepted:false,components:[]};const out=components.map(c=>{if(c.city!=='stuttgart'||!ownerF203Identity(c))return c;const d=reconstructF203Component(c);if(!d){stats.error='F203 exactsource mismatch';return c;}const vertices=d.batches.reduce((s,b)=>s+b.positions.length/3,0),triangles=d.batches.reduce((s,b)=>s+b.indices.length/3,0);stats.objects++;stats.vertices+=vertices;stats.triangles+=triangles;stats.originalVertices+=c.batches.reduce((s,b)=>s+b.positions.length/3,0);stats.components.push({objectId:c.objectId,partId:c.partId,sourcePartId:c.partId,patchSHA256:F203_RECONSTRUCTION_SHA,vertices,triangles,geometryRole:'owner-authorized-complete-native-church-display'});return d;});return{components:out,stats};}
